#include <stdio.h>
#include <string.h>

int main(void) {
    int N;
    char P[100005];

    if (scanf("%d", &N) != 1 || scanf("%100000s", P) != 1) {
        return 0;
    }

    for (int d = 1; d <= N / 2; d++) {
        if (N % d != 0) {
            continue;
        }

        int root[26] = {0};
        for (int i = 0; i < d; i++) {
            root[P[i] - 'a']++;
        }

        int valid = 1;
        for (int start = d; start < N && valid; start += d) {
            int count[26] = {0};

            for (int i = start; i < start + d; i++) {
                count[P[i] - 'a']++;
            }

            for (int c = 0; c < 26; c++) {
                if (count[c] != root[c]) {
                    valid = 0;
                    break;
                }
            }
        }

        if (valid) {
            printf("%.*s\n", d, P);
            return 0;
        }
    }

    puts("*");
    return 0;
}
